### Python

```python
import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    # 1. 计算从第一盏灯开始的交错和 S1
    S = 0
    for i in range(n):
        if i % 2 == 0:
            S += a[i]
        else:
            S -= a[i]

    # c = (-1)^(n-1)
    c = 1 if n % 2 == 1 else -1

    ans = S
    # 2. 递推计算其他起点的交错和
    for k in range(n - 1):
        S = -(S - a[k]) + c * a[k]
        if S > ans:
            ans = S

    print(ans)

if __name__ == "__main__":
    main()
```

